import{AMOUNTS,normalizeState,sortDrinks,cleanNutrition,nutrientTotals,validGoal,progress,localDate,localTime,liters,totals,csv,parseCsv,mergeImport}from'./core.js?v=4';
import{createDrinkSettings}from'./drink-settings.js?v=4';
import{createReminder}from'./reminder.js?v=4';
import{createStatistics}from'./statistics.js?v=5';
const $=id=>document.getElementById(id), KEY='trinkjournal.v1';
let state=normalizeState(),blocked=false,selection=null,undoAction=null,toastTimer,installEvent,drinkManager,reminderManager,statsManager;
function warning(message){$('storage-warning').textContent=message;$('storage-warning').hidden=false}
try{const raw=localStorage.getItem(KEY);if(raw)state=normalizeState(JSON.parse(raw))}catch{blocked=true;warning('Die gespeicherten Daten können nicht geladen werden. Es werden keine Daten überschrieben. Bitte prüfe, ob der Browserspeicher verfügbar ist.')}
function commit(next){if(blocked){notify('Speichern ist derzeit nicht möglich.');return false}try{localStorage.setItem(KEY,JSON.stringify(next));state=next;return true}catch{warning('Der Browser konnte die Daten nicht speichern. Dieser Eintrag wurde nicht gespeichert. Bitte exportiere vorhandene Einträge und prüfe den freien Speicher.');return false}}
function element(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function amountOptions(select,value){select.replaceChildren(...AMOUNTS.map(ml=>{const o=element('option','',liters(ml)+' l');o.value=ml;return o}));select.value=String(value)}
function notify(message,undo){clearTimeout(toastTimer);$('toast-text').textContent=message;$('toast').hidden=false;undoAction=undo;$('undo').hidden=!undo;toastTimer=setTimeout(()=>$('toast').hidden=true,undo?10000:4000)}
$('undo').onclick=()=>{if(undoAction)undoAction();$('toast').hidden=true;undoAction=null};
$('day').value=localDate();
function dayEntries(){return state.entries.filter(e=>e.day===$('day').value)}
function render(){const entries=dayEntries(),t=totals(entries);$('total').textContent=liters(t.ml);$('count').textContent=entries.length+' '+(entries.length===1?'Getränk':'Getränke');$('types').textContent=t.groups.length+' '+(t.groups.length===1?'Getränkeart':'Getränkearten');$('day-label').textContent=$('day').value===localDate()?'Heute getrunken':'An diesem Tag getrunken';const date=new Date($('day').value+'T12:00:00');$('timeline-date').textContent=new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'2-digit',year:'numeric'}).format(date);$('today').hidden=$('day').value===localDate();
 const goal=progress(t.ml,state.goalMl);$('goal-label').textContent='Tagesziel: '+liters(state.goalMl)+' l';$('goal-percent').textContent=goal.percent+' %';$('goal-fill').style.width=goal.fill+'%';$('goal-progress').setAttribute('aria-valuenow',String(Math.min(100,goal.percent)));$('goal-progress').setAttribute('aria-valuetext',goal.percent+' Prozent · '+liters(t.ml)+' von '+liters(state.goalMl)+' Litern');
 $('drinks').replaceChildren(...state.drinks.filter(d=>d.favorite).map(d=>{const b=element('button','drink-card');b.type='button';b.setAttribute('aria-label',d.name+' erfassen, Standard '+liters(d.ml)+' Liter');b.append(element('span','plus','＋'),element('span','drink-name',d.name),element('span','drink-amount',liters(d.ml)+' l'));b.onclick=()=>openEntry(d);return b}));
 if(!state.drinks.some(d=>d.favorite))$('drinks').append(element('p','section-hint','Keine Favoriten. Aktiviere Getränke mit dem Stern in den Einstellungen.'));
 renderNutrition(entries);
 $('summary').replaceChildren();if(!entries.length){$('summary').append(element('div','empty','Keine Einträge für diesen Tag.'))}else{for(const[name,ml]of t.groups){const r=element('div','summary-row'),line=element('div','summary-line'),track=element('div','bar-track'),bar=element('div','bar');line.append(element('span','',name),element('strong','',liters(ml)));bar.style.width=(ml/t.ml*100)+'%';track.append(bar);r.append(line,track);$('summary').append(r)}const total=element('div','summary-total');total.append(element('strong','','Gesamt'),element('strong','',liters(t.ml)+' l'));$('summary').append(total)}
 $('entries').replaceChildren();if(!entries.length){const e=element('div','empty');e.append(element('strong','','Keine Einträge für diesen Tag.'),document.createTextNode('Getränk auswählen, um einen Eintrag hinzuzufügen.'));$('entries').append(e)}else for(const e of [...entries].sort((a,b)=>b.time.localeCompare(a.time)||b.createdAt-a.createdAt)){const row=element('div','entry-row'),time=element('time','',e.time),del=element('button','delete-entry','×');time.dateTime=e.day+'T'+e.time;del.setAttribute('aria-label',e.name+' um '+e.time+' löschen');del.onclick=()=>{if(commit({...state,entries:state.entries.filter(x=>x.id!==e.id)})){render();notify('Eintrag gelöscht.',()=>{if(commit({...state,entries:[...state.entries,e]}))render()})}};row.append(time,element('span','entry-icon',e.emoji||'🥤'),element('span','entry-name',e.name),element('span','entry-volume',liters(e.ml)+' l'),del);$('entries').append(row)}
 $('export-day').disabled=!entries.length;$('export-all').disabled=!state.entries.length;
 statsManager?.refresh();
}
function openEntry(d){const now=new Date();selection={drink:structuredClone(d),day:$('day').value,time:localTime(now),createdAt:now.getTime()};$('entry-title').textContent=d.name;amountOptions($('amount'),d.ml);$('time').value=selection.time;$('entry-date').textContent=new Intl.DateTimeFormat('de-DE',{dateStyle:'full'}).format(new Date(selection.day+'T12:00:00'));$('entry-dialog').showModal()}
$('entry-form').onsubmit=e=>{e.preventDefault();if(!selection)return;const ml=Number($('amount').value);if(!AMOUNTS.includes(ml))return;const entry={id:crypto.randomUUID(),drinkId:selection.drink.id,name:selection.drink.name,emoji:selection.drink.emoji,day:selection.day,time:$('time').value,ml,createdAt:selection.createdAt,nutrition:cleanNutrition(selection.drink.nutrition)};if(commit({...state,entries:[...state.entries,entry]})){$('entry-dialog').close();$('reminder-banner').hidden=true;selection=null;render();notify(entry.name+' · '+liters(ml)+' l gespeichert.')}};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('day').onchange=()=>{if(!$('day').value)$('day').value=localDate();render()};
function moveDay(step){const d=new Date($('day').value+'T12:00:00');d.setDate(d.getDate()+step);$('day').value=localDate(d);render()}
$('prev').onclick=()=>moveDay(-1);$('next').onclick=()=>moveDay(1);$('today').onclick=()=>{$('day').value=localDate();render()};
function renderSettings(){drinkManager.render()}
function openSettings(focus=false){renderSettings();reminderManager.syncForm();amountOptions($('drink-default'),300);$('daily-goal').value=String(state.goalMl/1000);$('settings-dialog').showModal();if(focus)$('drink-name').focus()}
function saveGoal(){const input=$('daily-goal'),ml=Math.round(Number(input.value)*1000);if(input.validity?.badInput||!validGoal(ml))return;if(commit({...state,goalMl:ml}))render()}
$('daily-goal').oninput=saveGoal;$('goal-form').onsubmit=e=>{e.preventDefault();saveGoal()};
$('settings').onclick=()=>openSettings();$('add-drink').onclick=()=>openSettings(true);
$('drink-form').onsubmit=e=>{e.preventDefault();const name=$('drink-name').value.trim(),ml=Number($('drink-default').value);if(!name||!AMOUNTS.includes(ml))return;let drinks=[...state.drinks,{id:crypto.randomUUID(),name,ml,emoji:'🥤',favorite:true,nutrition:cleanNutrition()}];if(state.drinkOrder==='alphabetical')drinks=sortDrinks(drinks);if(commit({...state,drinks})){$('drink-name').value='';renderSettings();render();notify('Getränk hinzugefügt.')}};
$('drink-name').oninput=()=>$('drink-name').setCustomValidity('');
function download(entries,filename){if(!entries.length)return;const url=URL.createObjectURL(new Blob([csv(entries)],{type:'text/csv;charset=utf-8'}));const a=element('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('export-day').onclick=()=>download(dayEntries(),'trinkjournal-'+$('day').value+'.csv');$('export-all').onclick=()=>download(state.entries,'trinkjournal-alle-tage.csv');
let pendingImport=null,importVersion=0;
$('import-open').onclick=()=>{pendingImport=null;importVersion++;$('import-file').value='';$('import-status').textContent='';$('import-confirm').disabled=true;$('import-dialog').showModal()};
$('import-file').onchange=async()=>{const version=++importVersion;pendingImport=null;$('import-confirm').disabled=true;$('import-status').textContent='Datei wird geprüft …';try{const file=$('import-file').files[0];if(!file){$('import-status').textContent='';return}if(file.size>5*1024*1024)throw Error('Die Datei ist zu groß (maximal 5 MB).');const incoming=parseCsv(await file.text());if(version!==importVersion)return;const result=mergeImport(state.entries,incoming);pendingImport=incoming;$('import-status').textContent=result.additions.length+' neue Einträge · '+result.skipped+' bereits vorhanden.'+(incoming.length?'':' Die Datei enthält keine Einträge.');$('import-confirm').disabled=!result.additions.length}catch(error){if(version===importVersion)$('import-status').textContent=error.message}};
$('import-confirm').onclick=()=>{if(!pendingImport)return;const {additions,skipped}=mergeImport(state.entries,pendingImport);if(!additions.length){$('import-status').textContent='Alle Einträge sind bereits vorhanden.';$('import-confirm').disabled=true;return}const drinks=[...state.drinks],entries=additions.map(e=>{let d=drinks.find(d=>d.name===e.name&&d.ml===e.ml);if(!d){d={id:crypto.randomUUID(),name:e.name,ml:e.ml,emoji:'🥤',favorite:true,nutrition:cleanNutrition(e.nutrition)};drinks.push(d)}return {...e,id:crypto.randomUUID(),drinkId:d.id,emoji:d.emoji,createdAt:Date.now()}});if(commit({...state,drinks,entries:[...state.entries,...entries]})){pendingImport=null;$('import-dialog').close();render();notify(entries.length+' Einträge importiert'+(skipped?', '+skipped+' übersprungen.':'.'))}};
document.querySelectorAll('#app-menu button').forEach(b=>b.addEventListener('click',()=>{$('app-menu').open=false}));
document.addEventListener('click',e=>{if(!$('app-menu').contains(e.target))$('app-menu').open=false});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('app-menu').open){$('app-menu').open=false;$('app-menu').querySelector('summary').focus()}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;$('install').hidden=false});$('install').onclick=async()=>{if(installEvent){await installEvent.prompt();installEvent=null;$('install').hidden=true}};
window.addEventListener('appinstalled',()=>$('install').hidden=true);
window.addEventListener('storage',e=>{if(e.key===KEY)location.reload()});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>notify('Offline-Modus ist derzeit nicht verfügbar.'));
function renderNutrition(entries){
 const n=nutrientTotals(entries),format=v=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:2}).format(v),box=$('nutrition-summary');box.replaceChildren();
 for(const[key,title,unit]of [['alcohol','Reiner Alkohol','ml'],['kcal','Energie','kcal'],['sugar','Zucker','g'],['sweetenerMgL','Süßstoffe','mg'],['caffeine','Koffein','mg']]){const v=n[key];if(!v.known)continue;const row=element('div','nutrient-row'),line=element('div','summary-line');line.append(element('span','',title),element('strong','',format(v.value)+' '+unit));row.append(line);const detail=key==='alcohol'?' ≈ '+format(v.value*.8)+' g':key==='kcal'?' ≈ '+format(v.value*4.184)+' kJ':'';row.append(element('span','nutrient-coverage',(v.known===entries.length?'Alle':v.known+' von '+entries.length)+' Einträge'+detail));box.append(row)}
 $('nutrition-section').hidden=!Object.values(n).some(v=>v.known>0);
}
drinkManager=createDrinkSettings({getState:()=>state,commit,render,notify,element,amountOptions});
reminderManager=createReminder({getState:()=>state,commit,notify});
statsManager=createStatistics({getEntries:()=>state.entries,getDay:()=>$('day').value});
render();
